head.script:
// https://inswave01.atlassian.net/browse/WAEA-1133



// 테스트 설명, 유효성 값 설정
//  _1 : 기본 구성 (Body 가 MultiLine 일때의 rowIndex / colIndex 하위절은 _2 샘플에서 다루므로 제외)
scwin.tData = {
    "description" : "[gridView > E > oneditkeydown]<br/>Body Cell 의 편집 영역에서 키보드의 키를 누를때 발생합니다.",
    "validation" : [
        "Body Cell 이 편집 상태일때만 발생하며 Tab, Enter, Escape 등의 특수키를 누른 경우엔 발생하지 않습니다.",
        "info 파라미터로 편집중인 Body Cell 의 정보가 객체로 전달됩니다.",
        "info.rowIndex 는 편집중인 Body Cell 의 Row 인덱스값을 갖습니다.",
        "info.rowIndex 는 GridView 에 표시된 Row 를 기준으로 인덱스가 설정됩니다.",
        "info.rowIndex 는 DrillDown 으로 숨겨진 Row 를 인덱스에 포함하지 않습니다.",
        "info.colIndex 는 편집중인 Body Cell 의 Column 인덱스값을 갖습니다.",
        "info.colIndex 는 숨겨진 Column 도 포함하여 인덱스가 설정됩니다.",
        "info.colID 는 편집중인 Body Cell 의 ID 값을 갖습니다.",
        "info.keyCode 는 눌려진 키의 코드값을 갖습니다.",
        "info.keyCode 는 조합형 문자의 경우 229 값을 갖습니다.",
        "info.oldValue 는 키가 눌려지기 전 Body Cell 값을 갖습니다.",
        "info.oldValue 는 Body Cell 이 embeddedInput=true, inputType='text','secret','textImage' 인 경우에만 속성이 전달됩니다.",
        "Body Cell 이 embeddedInput=true, inputType='text','secret','textImage' 이면 Tab, Enter, Escape 등의 특수키가 눌렸을때도 oneditkeydown 이벤트가 발생합니다.",
        "GridView 가 편집 상태일때 키를 입력하면 onkeydown -> oneditkeydown -> onkeyup -> oneditkeyup 순서로 이벤트가 발생합니다."
    ]
}



//  seq       : 한 번의 키 조작(누름 -> 뗌) 안에서 이벤트 발생 순번
//  cycleDone : 직전 조작이 끝났는지 여부 (다음 누름 이벤트에서 순번을 1 부터 다시 시작)
scwin.gVar = { "seq" : 0, "cycleDone" : true };



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값을 명시 설정
    con_embeddedInput.setSelectedIndex(0);

    // comp 초기 생성 (비동기 dynamicCreate 완료까지 대기)
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
//  editable="true" 로 편집 가능한 GridView 를 구성한다.
//  Body Column 5개 (인덱스 0~4) - inputType 을 다양하게 배치하여 대비 검증
//   - 인덱스 0 : drilldown (이름) -> 토글로 자식 Row 를 접었다 펼치며 표시 Row 인덱스 변화를 확인
//   - 인덱스 1 : text (메모) -> setColumnVisible(1, false) 로 숨김. 숨겨진 Column 도 인덱스에 포함되는지 검증용
//   - 인덱스 2 : text      (텍스트)
//   - 인덱스 3 : secret    (비밀)
//   - 인덱스 4 : textImage (아이콘)
//  embeddedInput 은 con_embeddedInput 선택값을 모든 Body Column 에 동일하게 적용한다.
//   - true      : Cell 안에 항상 입력창이 표시되어 특수키에서도 발생 / oldValue 전달
//   - false/미설정 : 더블클릭으로 편집 진입. 특수키에서 미발생 / oldValue 미전달
//   - 미설정은 embeddedInput 속성 자체를 부여하지 않는다.
//  onkeydown / oneditkeydown / onkeyup / oneditkeyup 4개 이벤트를 모두 등록하여 발생 순서를 확인한다.
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    scwin.gVar.seq = 0;
    scwin.gVar.cycleDone = true;

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // con 옵션 읽기 (미설정이면 embeddedInput 속성 자체를 부여하지 않음)
    let embeddedInputVal = con_embeddedInput.getValue();
    let embeddedInputAttr = embeddedInputVal === '' ? '' : ' embeddedInput="' + embeddedInputVal + '"';
    let embeddedInputDisp = embeddedInputVal === '' ? '미설정' : embeddedInputVal;

    // 조작 절차 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] 편집 가능(editable=true) 그리드이며 Body Column 인덱스 0=이름(drilldown), 1=메모(text, 숨김 Column), 2=텍스트(text), 3=비밀(secret), 4=아이콘(textImage) 입니다.\n[전제] 모든 Body Column 에 con_embeddedInput 선택값이 embeddedInput 속성으로 적용되며 기본값은 미설정입니다 (현재 ' + embeddedInputDisp + '). 값을 바꾼 뒤에는 Target 재생성 버튼을 눌러야 반영됩니다.\n[전제] 표시 Row 순서는 영업본부(0) - 영업1팀(1) - 영업2팀(2) - 개발본부(3) - 개발1팀(4) - 관리팀(5) 입니다.\n[안내] embeddedInput=true 설정은 oldValue 전달 조건과 특수키에서의 이벤트 발생을 다루는 유효성 (11) (12) (13) 항목을 확인할 때만 필요하며, 나머지 항목은 모두 기본값인 미설정 상태에서 확인합니다.\n[절차1] 미설정 상태에서 텍스트 / 비밀 / 아이콘 Cell 을 각각 더블클릭해 편집 상태로 만든 뒤 일반 문자키를 누르고, 이어서 Tab / Enter / Escape 키를 각각 눌러 결과를 비교합니다.\n[절차2] 미설정 상태에서 개발본부 Row 의 Cell 에 키를 입력해 rowIndex 를 확인한 뒤, 영업본부 왼쪽의 토글 아이콘을 클릭해 자식 2건(영업1팀 / 영업2팀)을 접고 같은 Cell 에서 다시 키를 입력합니다.\n[절차3] 미설정 상태에서 Cell 을 편집 상태로 만든 뒤 입력기를 한글로 전환해 한글을 입력하고 조합형 문자일 때의 코드값을 확인합니다.\n[절차4] 미설정 상태의 결과창에서 각 줄 앞의 순번으로 네 이벤트의 발생 순서를 확인합니다.\n[절차5] 유효성 (11) (12) (13) 항목을 확인할 때만 con_embeddedInput 을 true 로 바꾸고 Target 재생성 버튼을 누른 뒤, Cell 안에 항상 표시되는 입력창을 클릭해 커서를 두고 일반 문자키와 Tab / Enter / Escape 키를 각각 눌러 절차1 결과와 비교합니다.\n[확인] Cell 종류별로 출력된 정보값을 비교하고, oldValue 줄이 미설정일 때는 속성 미전달로, true 일 때는 키가 눌리기 전 Cell 값으로 출력되는지 확인합니다."', '', 'label1');

    // dataList 생성 (6 Column, 6 Row)
    //  - name / memo / etxt / esec / eimg 는 Body Column 인덱스 0~4 와 순서가 일치
    //  - depth 는 drilldown Column 의 계층 정보(부모=1, 자식=2) 로만 사용하며 화면에는 표시하지 않음
    let strData = '';
    strData += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strData += '<w2:columnInfo>';
    strData += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strData += '<w2:column id="memo" name="memo" dataType="text"></w2:column>';
    strData += '<w2:column id="etxt" name="etxt" dataType="text"></w2:column>';
    strData += '<w2:column id="esec" name="esec" dataType="text"></w2:column>';
    strData += '<w2:column id="eimg" name="eimg" dataType="text"></w2:column>';
    strData += '<w2:column id="depth" name="depth" dataType="number"></w2:column>';
    strData += '</w2:columnInfo>';
    strData += '<w2:data use="true"></w2:data>';
    strData += '</w2:dataList>';
    $p.data.create(strData);

    let jsonData = [
        { "name" : "영업본부", "memo" : "메모0", "etxt" : "텍스트0", "esec" : "비밀0", "eimg" : "아이콘0", "depth" : 1 },
        { "name" : "영업1팀", "memo" : "메모1", "etxt" : "텍스트1", "esec" : "비밀1", "eimg" : "아이콘1", "depth" : 2 },
        { "name" : "영업2팀", "memo" : "메모2", "etxt" : "텍스트2", "esec" : "비밀2", "eimg" : "아이콘2", "depth" : 2 },
        { "name" : "개발본부", "memo" : "메모3", "etxt" : "텍스트3", "esec" : "비밀3", "eimg" : "아이콘3", "depth" : 1 },
        { "name" : "개발1팀", "memo" : "메모4", "etxt" : "텍스트4", "esec" : "비밀4", "eimg" : "아이콘4", "depth" : 2 },
        { "name" : "관리팀", "memo" : "메모5", "etxt" : "텍스트5", "esec" : "비밀5", "eimg" : "아이콘5", "depth" : 1 }
    ];
    dlt_bind.setJSON(jsonData, false);

    let properties = {
        dataList : "data:dlt_bind",
        editable : "true"
    };
    let cList = $c.gcm.createCList(properties);

    // 편집 상태의 키 입력과 관련된 4개 이벤트를 모두 등록하여 발생 순서를 확인한다.
    let eList = $c.gcm.createEList(["onkeydown", "oneditkeydown", "onkeyup", "oneditkeyup"]);

    // target 생성
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' ' + eList + ' id="" style="width:860px;height:280px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="200" style="" inputType="text" id="hcol1" value="0 : 이름 (DrillDown)"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="hcol2" value="1 : 메모 (숨김)"></w2:column>';
    strTarget += '<w2:column width="150" style="" inputType="text" id="hcol3" value="2 : 텍스트"></w2:column>';
    strTarget += '<w2:column width="150" style="" inputType="text" id="hcol4" value="3 : 비밀"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol5" value="4 : 아이콘"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="200" style="" inputType="drilldown" depthColumn="depth" showDepth="2" depthStartIndex="1"' + embeddedInputAttr + ' id="name" dataList="name"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text"' + embeddedInputAttr + ' id="memo" dataList="memo"></w2:column>';
    strTarget += '<w2:column width="150" style="" inputType="text"' + embeddedInputAttr + ' id="etxt" dataList="etxt"></w2:column>';
    strTarget += '<w2:column width="150" style="" inputType="secret"' + embeddedInputAttr + ' id="esec" dataList="esec"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="textImage"' + embeddedInputAttr + ' imageSrc="/cm/images/base/ico_grid_del.svg" id="eimg" dataList="eimg"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);

    // 두번째 Column(인덱스 1) 숨김 -> 숨겨진 Column 도 인덱스에 포함되는지 검증용
    scwin.target1.setColumnVisible(1, false);
}



// 이벤트 발생 순서 출력 공통 함수
//  - 각 핸들러가 발생 즉시 한 줄씩 출력하므로 출력 순서 = 실제 발생 순서
//  - 순번은 키를 누르고 떼는 한 번의 조작(down -> up) 마다 1 부터 다시 시작한다.
scwin.logEvent = function (message, isDown) {
    if (isDown === true && scwin.gVar.cycleDone === true) {
        scwin.gVar.seq = 0;
        scwin.gVar.cycleDone = false;
    }
    scwin.gVar.seq++;
    wf_body_bottom.getObj("scwin").setReturnValue("[" + scwin.gVar.seq + "] " + message);
}



// 표시 Row 인덱스로 해당 Row 의 이름을 구한다 (DrillDown 으로 표시 인덱스가 바뀌는지 확인용)
scwin.getRowName = function (rowIndex) {
    try {
        let realIndex = target1.getRealRowIndex(rowIndex);
        return dlt_bind.getCellData(realIndex, "name");
    } catch (e) {
        return "확인 불가";
    }
}



// oneditkeydown : Body Cell 의 편집 영역에서 키를 누를때 발생 (검증 대상)
//  - 표준 DOM 이벤트 객체가 아닌 info 객체이므로 가이드에 명시된 속성을 각각 출력한다.
//  - oldValue 는 전달 조건이 있으므로 속성 존재 여부와 함께 출력한다.
scwin.target1_oneditkeydown = function (info) {
    let bottom = wf_body_bottom.getObj("scwin");
    scwin.logEvent("oneditkeydown 발생", true);
    bottom.setReturnValue("info 객체 전달 여부 : " + (info !== null && typeof info === "object"));
    bottom.setReturnValue("info.rowIndex : " + info.rowIndex + " (편집 Row : " + scwin.getRowName(info.rowIndex) + ")");
    bottom.setReturnValue("info.colIndex : " + info.colIndex);
    bottom.setReturnValue("info.colID : " + info.colID);
    bottom.setReturnValue("info.keyCode : " + info.keyCode);
    bottom.setReturnValue("info.oldValue : " + (Object.prototype.hasOwnProperty.call(info, "oldValue") ? info.oldValue : "속성 미전달"));
}



// 발생 순서 확인용 (onkeydown -> oneditkeydown -> onkeyup -> oneditkeyup)
scwin.target1_onkeydown = function (e) {
    scwin.logEvent("onkeydown 발생", true);
}

scwin.target1_onkeyup = function (e) {
    scwin.logEvent("onkeyup 발생", false);
    scwin.gVar.cycleDone = true;
}

scwin.target1_oneditkeyup = function (info) {
    scwin.logEvent("oneditkeyup 발생", false);
    scwin.gVar.cycleDone = true;
}
